\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=10cm,
    height=6cm,
    title={示例折线图},
    xlabel={X轴标签},
    ylabel={Y轴标签},
    xmin=0, xmax=10,
    ymin=0, ymax=100,
    xtick={0,2,4,6,8,10},
    ytick={0,20,40,60,80,100},
    legend pos=north west,
    grid=major,
    grid style={dashed,gray!30},
]

% 第一条折线
\addplot[
    color=blue,
    mark=square,
    ]
    coordinates {
    (1,20)
    (2,35)
    (3,45)
    (4,60)
    (5,75)
    (6,85)
    (7,90)
    (8,95)
    (9,98)
    (10,100)
    };
    \addlegendentry{数据集 A}

% 第二条折线
\addplot[
    color=red,
    mark=triangle,
    ]
    coordinates {
    (1,10)
    (2,25)
    (3,40)
    (4,55)
    (5,65)
    (6,70)
    (7,75)
    (8,80)
    (9,85)
    (10,90)
    };
    \addlegendentry{数据集 B}

% 第三条折线
\addplot[
    color=green,
    mark=*,
    ]
    coordinates {
    (1,5)
    (2,15)
    (3,30)
    (4,50)
    (5,60)
    (6,65)
    (7,70)
    (8,75)
    (9,80)
    (10,85)
    };
    \addlegendentry{数据集 C}

\end{axis}
\end{tikzpicture}
\end{document}
